import { JSON5 } from './json'
import { Validator as JsonSchemaValidator } from 'jsonschema'

const claimSchema = {
    id: '/.claims',
    type: 'object',
    patternProperties: {
        '.*': { type: 'array' },
    },
}

export function validateClaimsFile(json: string) {
    const parsedJson = JSON5.parse(json)
    const validator = new JsonSchemaValidator()
    const result = validator.validate(parsedJson, claimSchema)

    if (result.errors && result.errors.length > 0) {
        throw new Error(`Error reading .claims.json, ${result.errors[0]?.stack}`)
    }
}
